import type { SupabaseClient } from '@supabase/supabase-js';
import type { Database } from '../../../lib/database.types.ts';
const files: Record<string,string> = {"proposal": "", "budget": "", "eligibility": ""};
export async function seedBaseline(client: SupabaseClient<Database>) {
 for (const grant of [1,2,3]) for (const [name,encoded] of Object.entries(files)) {
  const bytes = Uint8Array.from(atob(encoded), c => c.charCodeAt(0));
  const { error } = await client.storage.from('evidence').upload(`baseline/${grant}/${name}.pdf`, bytes, { contentType: 'application/pdf', upsert: false });
  if (error && !/already exists|duplicate/i.test(error.message)) throw new Error('Baseline evidence could not be prepared.');
 }
}
